SELECT COUNT(1)
FROM herb_species s

    s.is_deleted = 0

        AND (
            s.herb_name LIKE CONCAT('%', #{query.keyword}, '%')
            OR s.herb_no LIKE CONCAT('%', #{query.keyword}, '%')
            OR s.alias_name LIKE CONCAT('%', #{query.keyword}, '%')
        )


        AND s.category_code = #{query.category}


        AND s.medicinal_part = #{query.medicinalPart}


        AND s.status = #{query.status}

